L:dict[str,tuple[str,str,list[tuple[str,str,str,str]],list[str]]]={
"物質組成與分類":("物質依組成分為純物質與混合物。純物質包括元素與化合物，具有固定組成；混合物含多種物質，比例可變，可利用成分的物理性質差異分離。","巨觀性質應連結微觀粒子。元素由同原子序的原子構成，化合物中元素以固定比例化學結合；溶液雖均勻，仍是溶劑與溶質形成的混合物。",[p("純物質與混合物","純物質有固定組成與特性，混合物的組成比例可變。","空氣含氮、氧等多種氣體，是均勻混合物。","把外觀均勻的溶液誤判為純物質。"),p("元素與化合物","元素不能用一般化學方法分解，化合物可藉化學反應分解。","水是氫與氧以固定比例結合的化合物。","把化合物當成保留各成分原性質的混合物。"),p("分離方法","依沸點、溶解度、粒徑或吸附性等差異選擇方法。","乙醇與水可利用沸點差以分餾分離。","用過濾分離已完全溶解的食鹽。")],[]),
"原子結構":("原子由帶正電的原子核與核外電子組成；原子核含質子與中子。原子序等於質子數並決定元素身分，質量數是質子數與中子數之和。","電子分布以量子化能階與軌域描述，不是固定行星軌道。同位素質子數相同而中子數不同；平均原子量是依天然同位素豐度計算的加權平均。",[p("原子序與質量數","原子序Z是質子數，質量數A是質子與中子總數。","²³Na有11個質子與12個中子。","把週期表的小數平均原子量當成單一原子的質量數。"),p("同位素","同元素同位素具有相同質子數、不同中子數。","碳-12與碳-14都是碳，化學性質相近但核穩定性不同。","認為同位素是不同元素。"),p("電子組態","電子依能量由低至高填入軌域，價電子影響化學性質。","鈉的最外層有1個價電子，容易形成Na⁺。","把軌域圖理解為電子沿固定圓形路徑運動。")],["質量數：A=Z+N。","平均原子量：Σ(同位素質量×分率)。"]),
"週期表與元素性質":("週期表依原子序排列，週期反映主要電子層，主族元素的族可連結價電子組態。元素性質呈週期變化，源自有效核電荷、遮蔽與電子層數的共同作用。","同週期由左至右原子半徑通常減小、游離能通常上升；同族向下電子層增加，原子半徑通常增大。趨勢有例外，應以電子組態解釋而非死背箭頭。",[p("族與週期","同族主族元素價電子組態相似，因此常有相近反應性。","Li、Na、K皆為第1族，常形成+1離子。","把同週期元素誤認為價電子數相同。"),p("原子半徑","同週期有效核電荷增加使半徑通常減小；同族向下電子層增加使半徑增大。","Na原子半徑通常大於Cl。","只看核電荷大小而忽略電子層與遮蔽。"),p("游離能與電負度","游離能衡量移除電子難易，電負度描述成鍵原子吸引電子能力。","F的電負度很高，與H成鍵時電子密度偏向F。","把電負度當成孤立原子取得電子時釋放的能量。")],[]),
"化學鍵":("化學鍵源自原子間靜電作用與能量降低。離子鍵常由陽、陰離子晶格形成；共價鍵由原子共享電子對；金屬鍵可用金屬陽離子與離域電子描述。","物質性質取決於整體結構，不只鍵名。離子晶體熔點高且熔融或水溶時導電；分子物質的沸點受分子間作用力影響；網狀共價固體通常堅硬且熔點高。",[p("離子鍵","相反電荷離子在晶格中以靜電力結合，不存在獨立NaCl分子。","NaCl熔融後離子可移動，因此可導電。","以為固態離子化合物有自由電子而導電。"),p("共價鍵與極性","共享電子對分布不均可形成極性鍵，分子極性還取決於幾何形狀。","H₂O的O-H鍵有極性且彎曲形狀使分子有淨偶極。","看到極性鍵就斷定整個分子一定有極性。"),p("分子間作用力","色散力、偶極作用與氫鍵影響熔沸點和溶解性。","水分子間氫鍵使水沸點高於同族較小氫化物的簡單預期。","把氫鍵誤當成分子內H-O共價鍵。")],[]),
"莫耳與化學計量":("莫耳是物質的量單位，1 mol含亞佛加厥常數個指定粒子。莫耳質量把巨觀質量連結到粒子數；計算前要明確指定粒子是原子、分子、離子或式量單位。","化學計量必須先配平方程式，再把已知量換成莫耳，依係數比求未知量。多個反應物同時給定時，要比較可支持的反應進度以判斷限制試劑；本單元不混入材料或環境模板。",[p("莫耳與粒子數","粒子數等於莫耳數乘亞佛加厥常數。","0.50 mol O₂含3.011×10²³個O₂分子與1.00 mol氧原子。","把1 mol任何物質誤認為質量都相同。"),p("莫耳質量","莫耳數等於樣品質量除以莫耳質量。","36.0 g H₂O除以18.0 g/mol等於2.00 mol。","將分子中的下標漏掉而算錯莫耳質量。"),p("限制試劑","各反應物莫耳數除以其係數，較小者限制反應進度與產物上限。","2H₂+O₂→2H₂O中，3 mol H₂與2 mol O₂反應時H₂為限制試劑，生成3 mol H₂O並剩0.5 mol O₂。","直接把質量較小的反應物判為限制試劑。")],["N=nN_A，N_A=6.022×10²³ mol⁻¹。","n=m/M。","化學計量：n_i/ν_i依平衡係數比較。","百分產率=(實際產量/理論產量)×100%。"]),
"溶液與濃度":("溶液是溶質均勻分散於溶劑形成的混合物。濃度可用莫耳濃度、質量百分濃度等表示，使用時必須辨認分子與分母以及溫度是否影響體積。","稀釋只增加溶劑，溶質莫耳數在無反應與無損失時保持不變。配製標準溶液應正確稱量、定量轉移並在容量瓶定容，不能用燒杯刻度代替。",[p("莫耳濃度","莫耳濃度是溶質莫耳數除以溶液體積，體積以L代入。","0.50 mol NaCl配成2.00 L溶液，濃度0.250 M。","用溶劑體積而非配成後溶液體積作分母。"),p("質量百分濃度","溶質質量除以溶液總質量再乘100%。","10 g糖加90 g水形成100 g溶液，質量百分濃度10%。","把溶劑質量當成分母。"),p("稀釋","稀釋前後溶質莫耳數不變，可用濃度乘體積相等。","取25.0 mL 2.00 M溶液稀釋至100.0 mL，濃度0.500 M。","把加入的水量誤當成稀釋後總體積。")],["莫耳濃度：C=n/V。","稀釋：C₁V₁=C₂V₂。","質量百分濃度=(溶質質量/溶液質量)×100%。"]),
"化學反應式":("化學反應式以正確化學式表示反應物、生成物及反應條件。配平只能調整式前係數，使每種元素原子數與總電荷守恆，不能改動化學式下標。","完整反應式可標示物態；水溶液離子反應可拆成完整離子式並刪去旁觀離子，得到淨離子式。係數表示粒子數或莫耳數比，通常不等於質量比。",[p("方程式配平","調整最簡整數係數使反應前後各元素原子數相等。","N₂+3H₂→2NH₃左右各有2 N與6 H。","為了配平而把NH₃下標改掉。"),p("物態與條件","(s)、(l)、(g)、(aq)說明物態，箭頭上可標示加熱或催化劑。","AgNO₃(aq)+NaCl(aq)生成AgCl(s)沉澱。","把催化劑寫成反應物並計入淨消耗。"),p("淨離子式","只保留實際改變的離子與物質，並同時守恆原子與電荷。","Ag⁺(aq)+Cl⁻(aq)→AgCl(s)。","刪除反應中真正參與反應的弱電解質。")],["配平例：N₂+3H₂→2NH₃。","沉澱淨離子式：Ag⁺+Cl⁻→AgCl(s)。"]),
"生活中的化學":("生活化學應以物質成分、反應與劑量解釋食品、清潔、藥品與燃燒現象。天然不等於安全，合成也不等於有害；風險取決於危害性、暴露量與使用方式。","清潔劑的親水端與疏水端可協助油污分散；食品添加物有特定用途與法規限量；藥品需依劑量與交互作用使用。判讀商品宣稱時應核對成分、濃度與證據。",[p("界面活性劑","分子同時具有親水與疏水部分，可形成微胞帶走油污。","肥皂在水中包覆油滴，使其較易被沖走。","認為清潔劑是把油脂變成不存在。"),p("劑量與風險","化學物風險同時受固有危害與暴露量影響。","含氯漂白水須按標示稀釋並保持通風。","用天然或人工標籤直接判斷毒性。"),p("安全混用","不同清潔劑可能反應產生危險氣體，應依標示單獨使用。","含氯漂白水與酸性清潔劑混合可能釋出氯氣。","為增強效果而任意混合家用清潔劑。")],[]),
"氣體與溶液":("理想氣體模型假設粒子體積與分子間作用可忽略，壓力來自粒子碰撞器壁。狀態方程連結壓力、體積、絕對溫度與莫耳數，溫度必須使用K。","氣體溶解度通常隨氣體分壓增加而上升，且多數氣體在水中的溶解度隨溫度上升而降低。計算前要區分氣相狀態量與溶液濃度。",[p("理想氣體定律","同一狀態的P、V、n、T須使用相容單位，T用絕對溫標。","1.00 mol理想氣體在273.15 K、1 atm時體積約22.4 L。","把25°C直接以25代入PV=nRT。"),p("分壓","理想混合氣體總壓等於各成分分壓和，分壓與莫耳分率成正比。","總壓1.0 atm且氧莫耳分率0.21時，氧分壓0.21 atm。","把各氣體體積比例直接加成超過總壓。"),p("氣體溶解度","定溫稀溶液中，氣體溶解濃度與其上方分壓近似成正比。","汽水開瓶後CO₂分壓下降，氣體逸出形成氣泡。","把所有固體溶解度的溫度趨勢套到氣體。")],["理想氣體：PV=nRT。","道耳頓定律：P_total=ΣP_i，P_i=x_iP_total。","亨利定律：C=k_HP（適用範圍內）。"]),
"反應熱":("反應熱描述定壓反應的焓變。放熱反應把能量傳給環境，ΔH為負；吸熱反應由環境吸收能量，ΔH為正。符號取決於系統觀點。","赫斯定律源自焓是狀態函數，可將已知反應式相加求目標焓變；反應倒寫時ΔH變號，係數倍增時ΔH也同比例改變。量熱法要明確界定吸熱者與散熱損失。",[p("焓變符號","定壓下ΔH=H生成物-H反應物，放熱為負、吸熱為正。","甲烷燃燒使環境升溫，其系統ΔH小於0。","以環境變熱就把反應ΔH寫成正值。"),p("赫斯定律","反應式可代數組合，對應焓變也以相同方式相加。","某反應倒寫後，原本-100 kJ的ΔH變為+100 kJ。","倒寫反應卻忘記改變ΔH正負。"),p("量熱法","忽略熱損時反應放熱量與量熱器及溶液吸熱量代數和為零。","100 g溶液升溫2.0 K，取c=4.18 J/(g·K)，吸熱836 J。","只用溶質質量計算整杯溶液吸熱。")],["ΔH=H_products-H_reactants。","量熱：q=mcΔT。","理想隔熱：q_reaction+q_surroundings=0。"]),
"反應速率":("反應速率是反應物濃度減少或生成物濃度增加的時間變化率，須用化學計量係數正規化，才能對同一反應得到一致速率。瞬時速率由濃度—時間曲線切線斜率取得。","速率取決於濃度、溫度、表面積、催化劑與反應機構。速率方程中的反應級數必須由實驗決定，通常不能直接從總反應係數推得；催化劑降低活化能但不改變平衡常數。",[p("速率定義","反應速率依係數校正各物種濃度變化，反應物項帶負號。","2A→B中A以0.20 M/s消耗，反應速率為0.10 M/s，B生成速率也為0.10 M/s。","忽略係數而使不同物種算出不同反應速率。"),p("速率方程","速率常數與反應級數由實驗資料求得。","若[A]加倍使初速率變四倍，其他條件不變時對A為二級。","直接用平衡方程式係數當反應級數。"),p("活化能與催化","催化劑提供較低活化能路徑，使正逆反應都加快。","催化劑讓系統較快到達同一平衡組成。","認為催化劑會改變ΔH或平衡常數。")],["一般速率：v=-(1/a)d[A]/dt=(1/c)d[C]/dt。","速率方程：v=k[A]^m[B]^n（級數由實驗決定）。","阿瑞尼斯式：k=Ae^(-E_a/RT)。"]),
"化學平衡":("可逆反應達動態平衡時，正逆反應速率相等，各物種濃度保持不變但反應仍持續。平衡常數由平衡濃度或分壓建立，純固體與純液體不列入。","反應商Q與K比較可判斷反應移動方向。改變濃度、壓力或溫度會依勒沙特列原理產生新平衡；只有溫度能改變同一反應的K，催化劑只加快到達平衡。",[p("動態平衡","平衡時正逆速率相等，不代表反應物與生成物濃度相等。","密閉容器中濃度不再改變時，微觀正逆反應仍持續。","把平衡理解為反應完全停止。"),p("平衡常數與反應商","Q使用當下濃度，Q<K時反應淨向生成物方向進行。","A⇌B且K=4，若Q=1則系統向右移動。","把初始濃度直接當成平衡濃度代入K。"),p("平衡移動","系統受擾動後會朝部分抵銷改變的方向建立新平衡。","放熱反應升溫等同增加生成物熱，平衡偏向吸熱的逆向。","認為加入催化劑會提高平衡產率。")],["aA+bB⇌cC+dD：K_c=[C]^c[D]^d/([A]^a[B]^b)。","Q與K：Q<K向右；Q>K向左。"]),
"酸鹼平衡":("布忍斯特酸提供質子，鹼接受質子；共軛酸鹼對只差一個H⁺。強弱描述解離平衡傾向，濃度描述含量，弱酸並不必然比稀強酸的pH高。","Ka、Kb量化弱酸弱鹼平衡，水的離子積連結[H⁺]與[OH⁻]。緩衝液以弱酸及其共軛鹼抵抗少量酸鹼加入；滴定曲線需依當量點前後主要物種選公式。",[p("酸鹼與共軛對","酸失去H⁺形成共軛鹼，鹼得到H⁺形成共軛酸。","NH₃接受H⁺形成NH₄⁺，兩者是共軛鹼酸對。","把酸鹼身分視為完全固定而不看反應對象。"),p("Ka、Kb與pH","Ka越大通常酸越強；25°C時pH=-log[H⁺]且K_w=[H⁺][OH⁻]=10⁻¹⁴。","[H⁺]=1.0×10⁻³ M時pH=3.00。","認為pH 2只比pH 3酸兩倍。"),p("緩衝與滴定","弱酸/共軛鹼緩衝可消耗少量外加H⁺或OH⁻，容量有限。","等濃度CH₃COOH/CH₃COO⁻緩衝液的pH約等於pKa。","在強酸強鹼滴定的所有區段都套緩衝公式。")],["pH=-log[H⁺]；pOH=-log[OH⁻]。","25°C：K_w=[H⁺][OH⁻]=1.0×10⁻¹⁴。","K_a=[H⁺][A⁻]/[HA]。","緩衝近似：pH=pK_a+log([A⁻]/[HA])。"]),
"氧化還原":("氧化還原涉及電子轉移與氧化數改變。氧化是失電子或氧化數上升，還原是得電子或氧化數下降；電子由還原劑轉移到氧化劑，兩過程必同時發生。","配平半反應要同時守恆原子與電荷，再使氧化、還原半反應的電子數相等後相加。酸性與鹼性介質的H₂O、H⁺、OH⁻處理不同，不能混用酸鹼中和模板取代電子追蹤。",[p("氧化數","單質氧化數為0；中性物種總和為0，離子中總和等於離子電荷。","KMnO₄中K為+1、O為-2，因此Mn為+7。","把化學式下標直接當作氧化數。"),p("氧化劑與還原劑","氧化劑得電子而被還原；還原劑失電子而被氧化。","Zn+Cu²⁺→Zn²⁺+Cu中Zn是還原劑、Cu²⁺是氧化劑。","依名稱誤認氧化劑本身被氧化。"),p("半反應配平","分開寫電子得失，平衡原子與總電荷後等電子數合併。","Zn→Zn²⁺+2e⁻與Cu²⁺+2e⁻→Cu相加後電子消去。","只平衡元素數而忽略總電荷。")],["氧化：Zn→Zn²⁺+2e⁻。","還原：Cu²⁺+2e⁻→Cu。","電子守恆：失去電子莫耳數=得到電子莫耳數。"]),
"電化學":("電化學把氧化還原與電能轉換相連。原電池用自發反應產生電能，陽極氧化、陰極還原，電子經外電路由陽極流向陰極，鹽橋以離子遷移維持電中性。","電解池用外加電源驅動非自發反應，陽極仍氧化、陰極仍還原，但電極正負極性與原電池不同。電極電位與能斯特方程描述化學條件，不應混入歐姆電路或磁場公式。",[p("原電池","原電池陽極通常為負極、陰極為正極，鹽橋傳遞離子而非電子。","丹尼爾電池中Zn陽極溶解，電子流向Cu陰極。","認為電子主要穿過鹽橋。"),p("電池電位","標準電池電位等於陰極還原電位減陽極還原電位，正值對應標準條件下自發。","E°陰極=0.34 V、E°陽極=-0.76 V，E°cell=1.10 V。","把兩個還原電位不分角色直接相加。"),p("電解與法拉第定律","通過電量決定電子莫耳數，再依半反應係數求沉積或生成量。","2.00 A通電965 s的電量1930 C，約0.0200 mol e⁻。","只用電流大小而漏掉通電時間。")],["E°cell=E°cathode-E°anode。","ΔG°=-nFE°cell。","Q=It；n(e⁻)=Q/F，F≈96485 C/mol。","25°C能斯特式：E=E°-(0.05916/n)logQ_r。"]),
"實驗與誤差":("化學實驗需依目的選量器、控制變因並記錄原始數據與不確定度。容量瓶用於定容、移液管精確移取固定體積、滴定管量取流出體積，器材不可任意互換。","隨機誤差造成數據散布，系統誤差造成一致偏差；增加重複次數不能消除未校正的系統誤差。結果應依有效數字表達，並用空白試驗、標準化與物料衡算檢查。",[p("量器選擇","量器用途與精度不同，讀取凹液面時視線應與液面水平。","滴定管初讀1.20 mL、末讀24.85 mL，流出23.65 mL。","把滴定管末讀值直接當成流出體積。"),p("誤差類型","隨機誤差影響精密度，系統誤差使平均結果偏離真值。","天平零點偏高0.010 g會使所有稱量一致偏高。","以多量幾次就認為可消除校正偏差。"),p("數據處理","計算保留守衛位，最後依量測精度與有效數字報告。","三次滴定相近值可取平均，明顯異常值需有理由才能排除。","為得到理想答案而任意刪除不一致數據。")],["平均值：x̄=Σx_i/n。","百分誤差=|實驗值-參考值|/|參考值|×100%。"]),
"有機化學入門":("有機化學研究碳化合物的結構、性質與反應。碳通常形成四個共價鍵，可建構鏈、支鏈與環；同分異構物具有相同分子式但不同連接或空間排列。","有機物的命名與反應要從碳骨架和官能基辨識。結構式比只寫分子式提供更多連接資訊；性質不能僅以『含碳』概括，還受官能基、分子大小與立體結構影響。",[p("碳骨架","碳可形成單、雙、三鍵與多樣骨架，是有機分子多樣性的基礎。","丁烷與異丁烷皆為C₄H₁₀但碳骨架不同。","認為相同分子式必代表相同物質。"),p("結構表示","縮寫結構式、鍵線式與立體表示法提供不同層次資訊。","CH₃CH₂OH顯示乙醇的兩碳鏈及末端羥基。","在鍵線式漏算線端與轉角的碳原子。"),p("官能基概念","官能基是主導一類有機物特徵反應的原子組合。","羥基使小分子醇能與水形成氫鍵。","以為同官能基化合物所有物理性質都完全相同。")],[]),
"烴與官能基":("烴只含碳、氫，可分烷、烯、炔與芳香烴。烷含單鍵，烯含C=C，炔含C≡C；不飽和鍵常是加成反應位置，芳香環則有不同的電子結構與反應性。","官能基分類包括羥基、羰基、羧基、酯基、胺基等。命名先選含主要官能基的母鏈並編號；沸點、溶解度與反應性需同時考慮官能基和碳鏈。",[p("烴的分類","飽和烷烴只有C-C單鍵，烯烴與炔烴含多重鍵。","乙烯C₂H₄可與Br₂加成使溴色褪去。","把苯的反應性直接等同一般烯烴。"),p("有機官能基","羥基-OH、羰基>C=O、羧基-COOH與酯基-COO-對應不同類別。","CH₃COOH含羧基，是羧酸；CH₃COOCH₃含酯基，是酯。","只看到氧原子就把化合物全判為醇。"),p("性質與結構","碳鏈增長通常增強色散力，極性官能基影響氫鍵與水溶性。","乙醇比乙烷更易溶於水，因乙醇羥基可與水形成氫鍵。","只用分子量預測所有沸點而忽略分子間作用力。")],["非環狀烷烴通式：C_nH_(2n+2)。","單烯烴通式：C_nH_(2n)。"]),
"醇醛酸酯":("醇含羥基，醛含末端羰基，羧酸含羧基，酯含酯基。官能基決定典型反應：一級醇可氧化成醛再成酸，羧酸與醇可在酸催化下酯化。","酯化是可逆平衡，常以除水或使用過量反應物提高產率。水解可使酯回到酸與醇；鹼性水解生成羧酸鹽。各類不能共享同一套空泛性質模板。",[p("醇的氧化","一級醇氧化可形成醛再形成羧酸，三級醇在溫和條件下較難氧化。","乙醇可氧化成乙醛，再進一步氧化成乙酸。","認為所有醇氧化都得到同一產物。"),p("羧酸與醛","羧酸可供質子呈弱酸性；醛的羰基末端帶氫，具特徵氧化反應。","乙醛可被氧化成乙酸，並可呈銀鏡反應。","只憑分子含氧就判斷是羧酸。"),p("酯化與水解","羧酸與醇可逆生成酯和水，酸催化加快正逆反應。","乙酸與乙醇生成乙酸乙酯和水。","把催化劑當成提高平衡常數與理論產率。")],["酯化：RCOOH+R′OH⇌RCOOR′+H₂O。","一級醇氧化：RCH₂OH→RCHO→RCOOH。"]),
"高分子材料":("高分子由許多單體連結成長鏈或網狀結構。加成聚合打開不飽和鍵而通常無小分子副產物；縮合聚合則由雙官能基單體連結並常釋出水等小分子。","熱塑性、熱固性與彈性體的差異與鏈間作用、支化及交聯程度有關。材料性能還受分子量、結晶度與添加劑影響；回收代碼不代表可無限循環或性能不變。",[p("加成聚合","含C=C單體可開鍵連成重複單元。","nCH₂=CH₂聚合形成聚乙烯[-CH₂-CH₂-]ₙ。","在重複單元中仍保留原單體雙鍵。"),p("縮合聚合","具有兩個以上官能基的單體逐步反應並常釋出小分子。","二元酸與二元醇縮合可形成聚酯並釋水。","認為所有聚合反應都沒有副產物。"),p("結構與材料性質","交聯提高形狀穩定與耐熱性，但通常降低再熔融加工能力。","熱固性樹脂高度交聯，固化後不易再熔塑。","把所有塑膠都視為同樣可加熱回收。")],["聚乙烯：nCH₂=CH₂→[-CH₂-CH₂-]ₙ。"]),
"環境化學":("環境化學追蹤污染物的來源、傳輸、轉化、累積與最終去向。濃度、毒性、持久性、生物累積性和暴露途徑共同決定風險，不能只以是否可偵測判定危害。","大氣、水體與土壤問題涉及不同反應：燃燒可產生酸雨前驅物與粒狀物，營養鹽過量可致優養化，溫室氣體改變地球能量平衡。治理需從源頭減量並用監測資料驗證。",[p("空氣污染","SO₂、NOₓ、臭氧與PM來源和二次反應不同，需分別控制。","SO₂在大氣氧化並溶於水可形成酸性沉降。","把平流層保護性臭氧與近地面污染臭氧混為一談。"),p("水體污染","過量氮磷促進藻類繁生，分解耗氧可造成缺氧。","農業肥料流入湖泊可能引發優養化與魚群死亡。","認為水清澈就一定沒有溶解污染物。"),p("風險與監測","風險評估需結合劑量反應、暴露時間與族群敏感度。","同濃度污染物經飲水長期暴露與短暫皮膚接觸的風險不同。","用單一次量測直接推論全年暴露。")],[]),
"材料化學":("材料化學連結組成、微觀結構、製程與性能。金屬、陶瓷、高分子、半導體與複合材料各有強度、韌性、導電性、耐熱性與密度等取捨。","摻雜、熱處理、晶粒控制與表面處理可改變性能。材料選擇還要考慮成本、可加工性、腐蝕、資源與生命週期；不能把材料名稱當成固定不變的性質清單。",[p("結構與性質","鍵結與微結構決定電子、原子或分子移動難易，進而影響性能。","陶瓷通常耐熱但較脆，金屬通常具延展與導電性。","認為同類材料的所有成分與性能完全相同。"),p("半導體摻雜","少量雜質可控制載子濃度，形成n型或p型半導體。","矽摻入五價磷可增加自由電子形成n型材料。","把摻雜理解為大量混合而不需控制純度。"),p("複合材料與選材","複合材料結合不同相以取得單一材料難兼具的性能。","碳纖維強化樹脂兼具較低密度與高比強度。","只比較單一強度數字而忽略方向性與使用環境。")],[]),
"化學素養題":("化學素養題把概念放入圖表、實驗、產品或環境情境。解題先辨認系統邊界、變因、單位與資料來源，再分清觀察、推論和模型假設。","計算題須寫出配平方程式與量的轉換；證據題需以數據支持有限範圍的結論。圖表相關不等於因果，宣稱也不能超出樣本、量測精度與化學原理。",[p("資料判讀","先讀軸、單位、圖例與誤差，再比較趨勢和異常值。","濃度—時間圖的切線斜率可估瞬時反應速率。","只看兩個端點而忽略尺度與誤差棒。"),p("模型與計算","選擇守恆、平衡或速率模型前，確認其條件與所求量。","限制試劑題先換成莫耳並按係數比比較。","看到化學式就直接用係數當質量比。"),p("證據與主張","結論要由資料直接支持，並交代限制與替代解釋。","單一溫度下速率較快不能證明所有溫度都服從同一關係。","把相關性或單次實驗宣稱為普遍因果。")],[]),
"分科化學總複習":("分科化學總複習以粒子觀、守恆、能量、速率與平衡串聯各章。先辨認題目屬於組成計量、結構鍵結、熱化學、動力學、平衡、電化學或有機反應，再選合適模型。","解題流程是定義系統、配平方程式、統一單位、列關係並核對結果。酸鹼、氧化還原與電化學可同時出現，但需分別追蹤質子、電子與電荷；公式須符合適用條件。",[p("守恆與計量","原子、質量、電荷和電子依情境守恆，係數連結莫耳比。","氧化還原配平後，失電子總數必等於得電子總數。","把係數比直接當成質量比。"),p("速率與平衡","速率說明到達狀態的快慢，平衡常數說明平衡組成傾向。","催化劑可加快正逆反應但不改變同溫下K。","把反應很快誤判為平衡常數一定很大。"),p("驗算與邊界","以單位、數量級、正負號、限制試劑與平衡方向檢查答案。","百分產率不合理超過100%時應檢查產品含水或量測誤差。","只因答案接近選項就忽略單位與化學可行性。")],["計量：n=m/M，N=nN_A。","平衡：比較Q與K。","熱化學：ΔG°=-RTlnK。","電化學：ΔG°=-nFE°。"]),
}

def details(r:tuple[str,str,list[tuple[str,str,str,str]],list[str]])->dict[str,Any]:
 a,b,pts,fs=r; return {"lessonText":[a,b],"readableLesson":[a,b],"formulas":fs,"keyPoints":[{"topic":t,"explanation":e,"example":x,"commonTrap":c} for t,e,x,c in pts]}
def rewrite(path:Path,batch_size:int)->dict[str,Any]:
 data=load_curriculum_js(path); books=[b for b in data["chemistry"] if b.get("stage")=="high_school"]; units=[u for b in books for u in b.get("units",[])]
 titles=[u["name"] for u in units]
 if set(titles)!=set(L): raise SystemExit(f"標題白名單不一致 missing={sorted(set(titles)-set(L))} extra={sorted(set(L)-set(titles))}")
 done=0; failed=[]; STATE.parent.mkdir(parents=True,exist_ok=True)
 for off in range(0,len(units),max(1,batch_size)):
  batch=units[off:off+max(1,batch_size)]
  for u in batch:
   u["lessonDetails"]=details(L[u["name"]])
   if u["name"]=="反應速率":
    u["lessonDetails"]["lessonText"][1]+="碰撞理論要求粒子碰撞時具有足夠能量與合適方向，才形成有效碰撞。"
